// Representative JSON.parse/JSON.stringify behavior, generated by pinned Node.
const inputs = [
  '0.125', '0.00001', '0.000001', '-0.000001', '0.0000001', '1e-7',
  '3.141592653589793', '0.12345678901234566', '0.12345678901234567',
  '1.0000000000000002', '333333333.33333329', '999999999.9999999',
  '9007199254740991', '9007199254740992', '9007199254740993',
  '1e20', '1e21', '-0', '-0.0',
];
const vectors = inputs.map(raw => {
  const value = JSON.parse(raw);
  const data = new DataView(new ArrayBuffer(8));
  data.setFloat64(0, value, false);
  return {raw, bits: data.getBigUint64(0, false).toString(16).padStart(16, '0'), json: JSON.stringify(value)};
});
console.log(JSON.stringify({source: 'Node JSON.parse and JSON.stringify', vectors}, null, 2));
